            Describe.Lean(DescribeId.Create("ambient-edge"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/PhysicalWheel.ambientEdge"), H("ambientEdge"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("D5.S3.Geometry.OriginalLabelTwoSum.Wheel.ambientEdge. For an injective f : Label ↪ Ambient, define the total edge at i by the original wheel edge of its unique preimage when one exists, and by the hub loop s(0,0) otherwise. The original nonground zero label also has its prescribed wheel value; extra ambient ghosts are explicitly assigned the loop.")), SourceText("Exact lexical source context (not a compiled telescope):\nnoncomputable section\nopen Set Finset SimpleGraph\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.Wheel\nvariable {Ambient VL : Type*} [Fintype Ambient] [DecidableEq Ambient]\n\nExact source definition:\ndef ambientEdge (f : Label ↪ Ambient) (i : Ambient) : Sym2 Label :=\n  if h : ∃ j : Label, f j = i then wheelGraphData.edge (Classical.choose h) else s(0,0)")), DescribeRole.Definition),
